result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ledger.py", "content": """"Append-only consent ledger with hash-chained tamper evidence.

Each line of consents.log is a JSON record:
    {seq, ts, subject, purpose, action, prev_hash, hash}

hash = sha256(canonical JSON of the record minus the "hash" field),
where canonical JSON is sorted keys and compact separators.

Invariants enforced by verify():
  * seq strictly increments from 1
  * prev_hash chains correctly (genesis prev_hash is 64 zeros)
  * recomputed hash matches the stored hash
  * timestamps never decrease
  * a revoke without a prior grant for that subject+purpose is invalid
"""

import hashlib
import json
import time

GENESIS_PREV_HASH = "0" * 64
FIELDS = ("seq", "ts", "subject", "purpose", "action", "prev_hash")
VALID_ACTIONS = ("grant", "revoke")


def _canonical(record):
    """Canonical JSON of the record without its 'hash' field."""
    payload = {k: record[k] for k in FIELDS}
    return json.dumps(payload, sort_keys=True, separators=(",", ":"))


def _record_hash(record):
    return hashlib.sha256(_canonical(record).encode("utf-8")).hexdigest()


class Ledger:
    def __init__(self, path="consents.log"):
        self.path = path

    # -- internal helpers -------------------------------------------------

    def _read_records(self):
        """Parse the log into a list of dicts (empty list if no file yet)."""
        records = []
        try:
            with open(self.path, "r", encoding="utf-8") as f:
                for lineno, line in enumerate(f, 1):
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        records.append(json.loads(line))
                    except json.JSONDecodeError as exc:
                        raise ValueError(
                            f"{self.path}:{lineno}: invalid JSON: {exc}"
                        ) from exc
        except FileNotFoundError:
            pass
        return records

    @staticmethod
    def _replay(records):
        """Replay records -> {(subject, purpose): last_action}."""
        state = {}
        for rec in records:
            state[(rec["subject"], rec["purpose"])] = rec["action"]
        return state

    # -- public API --------------------------------------------------------

    def append(self, subject, purpose, action):
        """Append a grant/revoke record; rejects orphan revokes."""
        if action not in VALID_ACTIONS:
            raise ValueError(f"invalid action {action!r}; must be 'grant' or 'revoke'")
        if not subject or not purpose:
            raise ValueError("subject and purpose must be non-empty")

        records = self._read_records()
        state = self._replay(records)
        if action == "revoke" and state.get((subject, purpose)) != "grant":
            raise ValueError(
                f"orphan revoke: no prior grant for ({subject!r}, {purpose!r})"
            )

        seq = len(records) + 1
        prev_hash = records[-1]["hash"] if records else GENESIS_PREV_HASH
        last_ts = records[-1]["ts"] if records else 0.0

        record = {
            "seq": seq,
            "ts": max(time.time(), last_ts),  # keep timestamps non-decreasing
            "subject": subject,
            "purpose": purpose,
            "action": action,
            "prev_hash": prev_hash,
        }
        record["hash"] = _record_hash(record)

        with open(self.path, "a", encoding="utf-8") as f:
            f.write(json.dumps(record, sort_keys=True) + "\n")
        return record

    def verify(self):
        """Validate all invariants. Returns (ok, first_bad_seq)."""
        records = self._read_records()
        prev_hash = GENESIS_PREV_HASH
        prev_ts = float("-inf")
        state = {}

        for i, rec in enumerate(records):
            expected_seq = i + 1

            try:
                rec_seq = rec["seq"]
                rec_ts = rec["ts"]
                rec_subject = rec["subject"]
                rec_purpose = rec["purpose"]
                rec_action = rec["action"]
                rec_prev = rec["prev_hash"]
                rec_hash = rec["hash"]
            except (KeyError, TypeError):
                return False, expected_seq

            # seq strictly increments from 1
            if rec_seq != expected_seq:
                return False, expected_seq
            # chain integrity
            if rec_prev != prev_hash:
                return False, expected_seq
            # tamper evidence: recomputed hash must match stored hash
            if _record_hash(rec) != rec_hash:
                return False, expected_seq
            # timestamps never decrease
            if rec_ts < prev_ts:
                return False, expected_seq
            # semantic validity during replay
            if rec_action not in VALID_ACTIONS:
                return False, expected_seq
            if rec_action == "revoke" and state.get((rec_subject, rec_purpose)) != "grant":
                return False, expected_seq

            state[(rec_subject, rec_purpose)] = rec_action
            prev_hash = rec_hash
            prev_ts = rec_ts

        return True, None

    def status(self, subject, purpose):
        """Replay the log to derive current consent state."""
        state = self._replay(self._read_records())
        action = state.get((subject, purpose))
        if action == "grant":
            return "granted"
        if action == "revoke":
            return "revoked"
        return "unknown"
